use kernel::{output::verify_record, value::read_json, Config, Input};
use serde_json::json;
use std::path::PathBuf;
fn main() {
    let root=PathBuf::from(std::env::args().nth(1).unwrap());
    let out=root.join("crates/kernel/复核/否证-r1-2-证据");
    let cfg=root.join("规格/内核配置-v1.json");
    let config=Config::parse(read_json(&cfg).unwrap()).unwrap();
    let mut results=Vec::new();
    for name in ["混做粉碎机两下游", "分流器三路轮询"] {
        for kind in ["original", "remove-formal", "remove-all", "false-scope", "false-count", "false-summary"] {
            let input=root.join(format!("数据/样例/{name}.json"));
            let path=if kind=="original" {root.join(format!("数据/样例/{name}-运行记录-kernel.json"))} else {out.join(format!("{name}-{kind}.json"))};
            let record=read_json(&path).unwrap();
            let result=verify_record(&record,Input::load(&input,&config,false).unwrap(),&config,&cfg);
            results.push(json!({"case":format!("{name}:{kind}"),"accepted":result.is_ok(),"error":result.err().map(|e|e.to_string())}));
        }
    }
    for name in ["ore-shortage","pending-historical-alias","after-closure-control"] {
        let path=out.join(format!("{name}-record.json"));
        let input=out.join(format!("{name}-input.json"));
        let result=verify_record(&read_json(&path).unwrap(),Input::load(&input,&config,false).unwrap(),&config,&cfg);
        results.push(json!({"case":name,"accepted":result.is_ok(),"error":result.err().map(|e|e.to_string())}));
    }
    println!("{}",serde_json::to_string_pretty(&results).unwrap());
}
